        new(68,"PED:US-CCSS-MATH:G2:U05:L01","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-1/preparation.html","8b95f1c712928a475193eb9bb76a77698d724a68e85231a340721f7531f018a1",
            ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.2"],
            ["Learning goal: You will make sense of a hundred as a unit composed of 10 tens or 100 ones.\nIn grade 1, you were introduced to a ten as a unit made of 10 ones. You used that understanding to represent two-digit numbers and add within 100. You used connecting cubes to make and break apart two-digit numbers.",
             "Key ideas:\n- Recognize that each hundred is composed of 100 ones or 10 tens\n- In grade 1, you were introduced to a ten as a unit made of 10 ones\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.",
             "Example 1: How many do you see? How do you see them? Andre added more blocks. What is the value of Andre’s blocks now? How many tens and ones are in this number? Andre made the same number with the fewest amount of blocks possible. Draw a base-ten diagram to show what Andre’s number looks like now. Use your base-ten blocks to help.\nApproach: “What is a number we could place in the fourth row? Use a pattern we discussed to explain how you know your number would belong.” (You could put 122 in the group with 92, 102, and 112. The ones place has a 2, it is getting bigger by 10, and I think the 1 should stay the same like in 102 and 112.)\nExample 2: Three students were looking at 100 small squares arranged like this: Match the diagrams to the statements. Label each diagram with A, B, or C. Be prepared to explain your matches. Priya said, “I see 100 ones.” Kiran said, “I see 10 tens.” Lin said, “I see 1 hundred.” ___ ___ ___ Represent \\(100 + 11\\) with blocks or a diagram.\nApproach: “If Andre used the fewest number of blocks, how many tens did he use?” (He had 10 tens.) “What if Andre wanted to use the greatest amount of blocks to show this number? What would he do?” (He’d decompose all the tens to use only ones. He’d use 100 ones.)",
             "Step 1: Identify what needs to be measured.\nStep 2: Choose the required unit and correct starting point.\nStep 3: Place or interpret equal-size units accurately.\nStep 4: Count or calculate the units and record the measure.\nStep 5: Check the endpoint, scale, and unit label.",
             "Common mistake: using unequal units, leaving gaps, overlapping units, or starting at the wrong point. Check the unit and endpoints.",
             "You will make sense of a hundred as a unit composed of 10 tens or 100 ones. In grade 1, you were introduced to a ten as a unit made of 10 ones."],
            ["Original 2021 IM Grade2 Unit5 Lesson1 — How Do We Compose a Hundred?. Count by ONES from90 through120; notice crossing99→100 and the 10-column pattern. Original Andre's 8 tens and16 ones =96. His next diagram has8 tens and20 ones =100. Trade ten tens for ONE hundred to use the fewest blocks. Activity2 match Priya's100 ones, Kiran's10 tens and Lin's1 hundred to actual publisher images; represent100+11=111 with blocks. Real paired base-ten work and actual original diagram labels need teacher review. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "10 ones =1 ten; 10 tens=100 ones=1 hundred. 8 tens and16 ones is96 (9 tens6 ones), whereas8 tens20 ones is100 (10 tens). Three drawings of the same quantity can show100 ones,10 tens or1 hundred. One hundred and11 ones is111, or1 hundred1 ten1 one. This lesson directly addresses CCSS:2.NBT.A.1, CCSS:2.NBT.A.2. ORIGINAL task evidence: Original Andre's 8 tens and16 ones =96. His next diagram has8 tens and20 ones =100. Trade ten tens for ONE hundred to use the fewest blocks. Activity2 match Priya's100 ones, Kiran's10 tens and Lin's1 hundred to actual publisher images; represent100+11=111 with blocks. Real paired base-ten work and actual original diagram labels need teacher review.",
             "Source96=8×10+16; source100=8×10+20; source100=10×10=1 hundred; original100+11=111. FIRST-PARTY PRACTICE BOUNDARY: Non-source authored practice: regroup noncanonical tens and ones, compose 100, count across100, represent100+n.",
             "1. Review the ORIGINAL lesson warm-up: Count by ONES from90 through120; notice crossing99→100 and the 10-column pattern. 2. Study original learner Activity1 and exact publisher quantities: Original Andre's 8 tens and16 ones =96. His next diagram has8 tens and20 ones =100. Trade ten tens for ONE hundred to use the fewest blocks. Activity2 match Priya's100 ones, Kiran's10 tens and Lin's1 hundred to actual publisher images; represent100+11=111 with blocks. Real paired base-ten work and actual original diagram labels need teacher review. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: Do not call8 tens16 ones '100'; exchange16 ones for1 ten and6 ones. A hundred is 10 tens, not one ten. A matching diagram with 100 ones does not have 100 tens. The original pupil-labelled diagrams require the actual image and teacher. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: Teacher checks actual block counts, the authentic Priya/Kiran/Lin visual match, drawings and partner talk; logged-in Cool-down Fewer Blocks is inaccessible.",
             "Do not call8 tens16 ones '100'; exchange16 ones for1 ten and6 ones. A hundred is 10 tens, not one ten. A matching diagram with 100 ones does not have 100 tens. The original pupil-labelled diagrams require the actual image and teacher. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L1: 10 ones =1 ten; 10 tens=100 ones=1 hundred. 8 tens and16 ones is96 (9 tens6 ones), whereas8 tens20 ones is100 (10 tens). Three drawings of the same quantity can show100 ones,10 tens or1 hundred. One hundred and11 ones is111, or1 hundred1 ten1 one. Teacher checks actual block counts, the authentic Priya/Kiran/Lin visual match, drawings and partner talk; logged-in Cool-down Fewer Blocks is inaccessible."],true),
        new(69,"PED:US-CCSS-MATH:G2:U05:L02","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-2/preparation.html","b007f773be8b6f7c7e1a91c85fbcf4c472c3f418dee2af93ac86de98451b6fba",
            ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.2"],
            ["Learning goal: You will represent hundreds in different ways.\nIn a previous lesson, you learned that a hundred is composed of 10 tens or 100 ones. In this lesson, you deepen your understanding of a hundred as a unit. You learn that for every 10 tens, you can compose 1 hundred.",
             "Key ideas:\n- Read, write, and represent multiples of 100\n- In a previous lesson, you learned that a hundred is composed of 10 tens or 100 ones\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.",
             "Example 1: Build each number using base-ten blocks. Record how many tens blocks you use. Build 90. Build 110. Build 150. ___ tens ___ tens ___ tens How many base-ten blocks would you need to build 200? ___ tens How many base-ten blocks would you need to build 300? ___ tens How many base-ten blocks would you need to build 300 if you could use 1 hundreds block? 1...\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.\nExample 2: Han and Jada represented the same number using base-ten blocks. They started base-ten diagrams, but ran out of time to finish them. Jada Han I only used hundreds. I only used tens. Total value: 700 Total value: 700 Use base-ten blocks to show what each student’s work would look like if they had time to finish it. Explain how you know both ways of using...\nApproach: “What did you notice about the number of tens and the number of hundreds?” (10 tens = 1 hundred, 20 tens = 2 hundreds, 30 tens = 3 hundreds) “How many hundreds would I have if I have 80 tens?” (8 hundreds)",
             "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
             "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
             "You will represent hundreds in different ways. In a previous lesson, you learned that a hundred is composed of 10 tens or 100 ones."],
            ["Original 2021 IM Grade2 Unit5 Lesson2 — Make Hundreds PLC Activity. Count by TENS from0 through300, noting patterns including beyond120. Activity1 in genuine group4 use at least50 ten-blocks and no hundred blocks: build90=9 tens,110=11,150=15,200=20,300=30; if one hundred block allowed for300 use20 tens; if two hundreds blocks allowed use10 tens; with only hundreds use3 hundred blocks and0 tens. Activity2 original Han and Jada both represent700: Jada started with4 hundreds and must complete to7; Han had15 tens drawn and must complete70 tens. Compare 70 tens=7 hundreds physically and on actual source drawings. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "Every ten-rod is worth ten: 90=9 tens,110=11 tens,150=15 tens. 300=30 tens=1 hundred+20 tens=2 hundreds+10 tens=3 hundreds. 700=7 hundred-blocks or70 ten-rods. Group any10 ten rods into1 hundred with unchanged total value. This lesson directly addresses CCSS:2.NBT.A.1, CCSS:2.NBT.A.2. ORIGINAL task evidence: Activity1 in genuine group4 use at least50 ten-blocks and no hundred blocks: build90=9 tens,110=11,150=15,200=20,300=30; if one hundred block allowed for300 use20 tens; if two hundreds blocks allowed use10 tens; with only hundreds use3 hundred blocks and0 tens. Activity2 original Han and Jada both represent700: Jada started with4 hundreds and must complete to7; Han had15 tens drawn and must complete70 tens. Compare 70 tens=7 hundreds physically and on actual source drawings.",
             "Source90=9 tens;110=11 tens;150=15 tens;200=20 tens;300=30 tens;300=100+20 tens;300=200+10 tens;700=70 tens=7 hundreds. FIRST-PARTY PRACTICE BOUNDARY: Independently authored group tens into hundreds, convert hundreds to tens, compute missing tens when using k hundred blocks.",
             "1. Review the ORIGINAL lesson warm-up: Count by TENS from0 through300, noting patterns including beyond120. 2. Study original learner Activity1 and exact publisher quantities: Activity1 in genuine group4 use at least50 ten-blocks and no hundred blocks: build90=9 tens,110=11,150=15,200=20,300=30; if one hundred block allowed for300 use20 tens; if two hundreds blocks allowed use10 tens; with only hundreds use3 hundred blocks and0 tens. Activity2 original Han and Jada both represent700: Jada started with4 hundreds and must complete to7; Han had15 tens drawn and must complete70 tens. Compare 70 tens=7 hundreds physically and on actual source drawings. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: Do not confuse 30 rods with30 ones; 30 ten-rods means300. Don't infer Han had only15 tens in full diagram;15 is the incomplete start, target70. Group activities and original picture completion remain real-world teacher reviewed. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: Teacher inspects actual source Jada and Han unfinished diagrams, physical ten rods and MLR8 group discussion; publisher Cool-down unavailable.",
             "Do not confuse 30 rods with30 ones; 30 ten-rods means300. Don't infer Han had only15 tens in full diagram;15 is the incomplete start, target70. Group activities and original picture completion remain real-world teacher reviewed. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L2: Every ten-rod is worth ten: 90=9 tens,110=11 tens,150=15 tens. 300=30 tens=1 hundred+20 tens=2 hundreds+10 tens=3 hundreds. 700=7 hundred-blocks or70 ten-rods. Group any10 ten rods into1 hundred with unchanged total value. Teacher inspects actual source Jada and Han unfinished diagrams, physical ten rods and MLR8 group discussion; publisher Cool-down unavailable."],true),
        new(70,"PED:US-CCSS-MATH:G2:U05:L03","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-3/preparation.html","0a79d7bc3df54dde4cf80c1994ab8668ded02660cdd94edd67562da0eb456b8e",
            ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.2","CCSS:2.NBT.B.5"],
            ["Learning goal: You will use base-ten representations to build an understanding of the digits in three-digit numbers.\nIn previous units, you used base-ten blocks and diagrams to compose and decompose tens when adding and subtracting by place. In previous lessons, you learned that a hundred is a unit that is made up of 10 tens and used base-ten blocks to show composing a hundred with 10 tens. In this lesson, you represent three-digit numbers that include an amount of hundreds, tens, and ones.",
             "Key ideas:\n- Compose three-digit numbers using place value understanding\n- In previous units, you used base-ten blocks and diagrams to compose and decompose tens when adding and subtracting by place\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.",
             "Example 1: Find the value of each expression mentally. \\(42+42\\) \\(21+63\\) \\(50+34\\) \\(48+36\\)\nApproach: “What did you notice about the sums?” (The expressions were all different, but all had a value of 84.) “How could you explain why the third and fourth expressions have the same value?” (You could take 2 ones from 36 and add it to 48 to make \\(50+34\\) .)\nExample 2: Mai’s Blocks Mai has ___ hundreds ___ tens ___ ones. Draw a base-ten diagram to represent the same total value with the fewest number of each unit. What is the value of Mai’s blocks? Diego’s Blocks Diego has ___ hundreds ___ tens ___ ones. Draw a base-ten diagram to represent the same total value with the fewest number of each unit. What is the value of...\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.",
             "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
             "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
             "You will use base-ten representations to build an understanding of the digits in three-digit numbers. In previous units, you used base-ten blocks and diagrams to compose and decompose tens when adding and subtracting by place."],
            ["Original 2021 IM Grade2 Unit5 Lesson3 — Compose Three-digit Numbers. Number Talk four distinct sums equal84:42+42,21+63,50+34,48+36. Explain tens/ones reorganization. Activity1 source group3–4 container has2 hundreds28 tens15 ones: value495; normalized fewest blocks4 hundreds9 tens5 ones. Real sort/group gallery walk. Activity2 Mai's real diagram1 hundred7 tens18 ones has value188 (1 hundred8 tens8 ones); Diego's source final value283 while his original block image must be consulted for complete starting block counts; compare diagrams and exchange units. Actual image interpretation and group display teacher-only. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "Value =100h+10t+o. Exchange10 ones for1 ten, exchange10 tens for1 hundred, until0≤t,o≤9. For2 hundreds28 tens15 ones, normalize200+280+15=495→4 hundreds9 tens5 ones. Mai1 hundred7 tens18 ones→1 hundred8 tens8 ones=188. Four warmup sums each equal84. This lesson directly addresses CCSS:2.NBT.A.1, CCSS:2.NBT.A.2, CCSS:2.NBT.B.5. ORIGINAL task evidence: Activity1 source group3–4 container has2 hundreds28 tens15 ones: value495; normalized fewest blocks4 hundreds9 tens5 ones. Real sort/group gallery walk. Activity2 Mai's real diagram1 hundred7 tens18 ones has value188 (1 hundred8 tens8 ones); Diego's source final value283 while his original block image must be consulted for complete starting block counts; compare diagrams and exchange units. Actual image interpretation and group display teacher-only.",
             "Original42+42=84,21+63=84,50+34=84,48+36=84; source2h+28t+15o=495=4h+9t+5o; Mai1h+7t+18o=188; Diego published total283. FIRST-PARTY PRACTICE BOUNDARY: Random but bounded noncanonical base-ten collections, normalized h/t/o, aggregate numbers and exchange invariants.",
             "1. Review the ORIGINAL lesson warm-up: Number Talk four distinct sums equal84:42+42,21+63,50+34,48+36. Explain tens/ones reorganization. 2. Study original learner Activity1 and exact publisher quantities: Activity1 source group3–4 container has2 hundreds28 tens15 ones: value495; normalized fewest blocks4 hundreds9 tens5 ones. Real sort/group gallery walk. Activity2 Mai's real diagram1 hundred7 tens18 ones has value188 (1 hundred8 tens8 ones); Diego's source final value283 while his original block image must be consulted for complete starting block counts; compare diagrams and exchange units. Actual image interpretation and group display teacher-only. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: After exchanging tens or ones the number of blocks changes but total value stays fixed. 2h+28t+15o is NOT 2h+8t+5o; ten-for-one exchanges require carrying. Do not invent Diego's source image composition from the text alone. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: Teacher examines actual base-ten buckets, original Mai/Diego pictures, MLR7 gallery and authentic pupil drawings; logged-in Cool-down withheld.",
             "After exchanging tens or ones the number of blocks changes but total value stays fixed. 2h+28t+15o is NOT 2h+8t+5o; ten-for-one exchanges require carrying. Do not invent Diego's source image composition from the text alone. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L3: Value =100h+10t+o. Exchange10 ones for1 ten, exchange10 tens for1 hundred, until0≤t,o≤9. For2 hundreds28 tens15 ones, normalize200+280+15=495→4 hundreds9 tens5 ones. Mai1 hundred7 tens18 ones→1 hundred8 tens8 ones=188. Four warmup sums each equal84. Teacher examines actual base-ten buckets, original Mai/Diego pictures, MLR7 gallery and authentic pupil drawings; logged-in Cool-down withheld."],true),
        new(71,"PED:US-CCSS-MATH:G2:U05:L04","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-4/preparation.html","f714865b7b652313f3d05f3708c0f3b4bca94450ca66151de3d32d03ed876f8f",
            ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.3"],
            ["Learning goal: You will use your understanding of place value to identify and write three-digit numbers.\nIn previous lessons, you learned that the three digits in a three-digit number represent amounts of hundreds, tens, and ones. In this lesson, you build on this understanding to write three-digit numbers when the number or value of the hundreds, tens, and ones are shown in different orders.",
             "Key ideas:\n- Read, write, and represent three-digit numbers using base-ten numerals\n- In previous lessons, you learned that the three digits in a three-digit number represent amounts of hundreds, tens, and ones\n- Choose a representation that matches the quantities and relationship, then use it to justify and check the result.",
             "Example 1: How many do you see and how do you see them?\nApproach: “What did you notice about the order of the blocks and the value the blocks represent?” (Even though the blocks were in different orders, the first two images had the same value. The order of the blocks doesn’t change the value of the blocks.)\nExample 2: Solve each riddle and write the three-digit number. Use the table to help you organize the digits. riddle hundreds tens ones three-digit number 1 2 3 4 5 6 I have 2 ones, 7 tens, and 6 hundreds. I have 3 ones, 5 tens, and 2 hundreds. I have 7 hundreds, 5 ones, and 3 tens. I have 5 hundreds, no tens, and 9 ones. I have 4 ones, 6 tens, and 3 hundreds. I...\nApproach: Represent the quantities or relationships clearly, apply the lesson idea, and check that the result answers the question.",
             "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
             "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
             "You will use your understanding of place value to identify and write three-digit numbers. In previous lessons, you learned that the three digits in a three-digit number represent amounts of hundreds, tens, and ones."],
            ["Original 2021 IM Grade2 Unit5 Lesson4 — Write Three-digit Numbers. How Many Do You See? Original images3 hundreds2 tens4 ones=324 (two different orders) and1 hundred2 tens7 ones=127. Activity1 six original number riddles, in order:6 hundreds7 tens2 ones=672;2h5t3o=253;7h3t5o=735;5h0t9o=509;3h6t4o=364;1h8t0o=180. Activity2 mixed-order source equations:4h+6t+2o=462,7o+2h+6t=267,3t+5h=530, 325=3h+5o+2t,70+300+2=372,836=6+800+30, and7o+3h is307 not37. Teacher observes actual pictured blocks and pupil partner explanations. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "Each digit has a fixed column: 100h+10t+o. Terms may appear in any order in an addition expression, but writing digits in numeral order always hundreds-tens-ones; place a ZERO when a place contains none. Thus 509 has0 tens, 180 has0 ones,307 has0 tens. This lesson directly addresses CCSS:2.NBT.A.1, CCSS:2.NBT.A.3. ORIGINAL task evidence: Activity1 six original number riddles, in order:6 hundreds7 tens2 ones=672;2h5t3o=253;7h3t5o=735;5h0t9o=509;3h6t4o=364;1h8t0o=180. Activity2 mixed-order source equations:4h+6t+2o=462,7o+2h+6t=267,3t+5h=530, 325=3h+5o+2t,70+300+2=372,836=6+800+30, and7o+3h is307 not37. Teacher observes actual pictured blocks and pupil partner explanations.",
             "Original source six riddles give672,253,735,509,364,180. Mixed-order4h+6t+2o=462;7o+2h+6t=267;3t+5h=530;325=3h+5o+2t;70+300+2=372;836=800+30+6. FIRST-PARTY PRACTICE BOUNDARY: Generate numerical three-digit riddles and out-of-order place addends with zeros in absent places.",
             "1. Review the ORIGINAL lesson warm-up: How Many Do You See? Original images3 hundreds2 tens4 ones=324 (two different orders) and1 hundred2 tens7 ones=127. 2. Study original learner Activity1 and exact publisher quantities: Activity1 six original number riddles, in order:6 hundreds7 tens2 ones=672;2h5t3o=253;7h3t5o=735;5h0t9o=509;3h6t4o=364;1h8t0o=180. Activity2 mixed-order source equations:4h+6t+2o=462,7o+2h+6t=267,3t+5h=530, 325=3h+5o+2t,70+300+2=372,836=6+800+30, and7o+3h is307 not37. Teacher observes actual pictured blocks and pupil partner explanations. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: 4 hundreds,3 ones,2 tens is423, not432 or234. 7 ones+3 hundreds is307, not37. Omitting zero means a different number; 509≠59. The numeric order in an expression can be rearranged but numeral digit position cannot. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: Teacher reviews genuine original picture and six handwritten riddles, explanation and additional student-authored clues; private Cool-down Order of Digits not reproduced.",
             "4 hundreds,3 ones,2 tens is423, not432 or234. 7 ones+3 hundreds is307, not37. Omitting zero means a different number; 509≠59. The numeric order in an expression can be rearranged but numeral digit position cannot. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L4: Each digit has a fixed column: 100h+10t+o. Terms may appear in any order in an addition expression, but writing digits in numeral order always hundreds-tens-ones; place a ZERO when a place contains none. Thus 509 has0 tens, 180 has0 ones,307 has0 tens. Teacher reviews genuine original picture and six handwritten riddles, explanation and additional student-authored clues; private Cool-down Order of Digits not reproduced."],false),
        new(72,"PED:US-CCSS-MATH:G2:U05:L05","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-5/preparation.html","0e7aa16652f3cd69fd74424460a333ed95dbfc52a44f9a9a207a73fc53ca3e81",
            ["CCSS:2.NBT.A.1","CCSS:2.NBT.A.3"],
            ["Learning goal: You will use expanded form and base-ten numerals to represent numbers within 1,000.\nIn previous lessons, you represented three-digit numbers by recording how many of each unit (for example, 357 as 3 hundreds, 5 tens, 7 ones). You also connected representations of a number using the fewest number of base-ten blocks to the value of the digits in three-digit numbers. In this lesson, you extend your understanding of ways to express the value of the digits in three-digit numbers to include expanded form .",
             "Key ideas:\n- Read, write, and represent three-digit numbers using base-ten numerals and expanded form\n- In previous lessons, you represented three-digit numbers by recording how many of each unit (for example, 357 as 3 hundreds, 5 tens, 7 ones)\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.",
             "Example 1: Decide if each statement is true or false. Be prepared to explain your reasoning. \\(800 + 90 + 7 = 897\\) \\(156 = 50 + 100 + 6\\) \\(407 = 70 + 400\\) \\(632 = 22 + 10 + 600\\)\nApproach: “What is different about the last equation?” (It’s not decomposed into hundreds, tens, and ones. 22 shows some tens and some ones and 10 shows another ten.)\nExample 2: Andre has 3 hundreds. Tyler has 5 tens. Mai has 7 ones. They want to represent the amount they have using an equation. Write an expression to represent the sum of their values. ___ + ___ + ___ Write the total value as a three-digit number: ___ Write each number as the sum of hundreds, tens, and ones, and as a three-digit number. Expanded form: ___...\nApproach: “What is the value of \\(40 + 100 + 3\\) ? Explain how you know.” (143. I saw there was 1 hundred, 4 tens, and 3 ones. I just rearranged it in my head like expanded form.) “How would we write 143 in expanded form?” ( \\(100 + 40 + 3\\) )",
             "Step 1: Identify what the task asks you to find or show.\nStep 2: Represent the important quantities or relationships.\nStep 3: Apply the key idea from the lesson.\nStep 4: Explain how the representation supports the result.\nStep 5: Check that the result matches the question.",
             "Common mistake: jumping to an answer before checking that the representation matches the quantities and relationship in the task.",
             "You will use expanded form and base-ten numerals to represent numbers within 1,000. In previous lessons, you represented three-digit numbers by recording how many of each unit (for example, 357 as 3 hundreds, 5 tens, 7 ones)."],
            ["Original 2021 IM Grade2 Unit5 Lesson5 — Expanded Form of Numbers. Original True/False 800+90+7=897 TRUE;156=50+100+6 TRUE;407=70+400 FALSE;632=22+10+600 TRUE (not conventional expanded form). Activity1 publisher 3h5t7o=357→300+50+7,1h9t2o=192,2h3t8o=238,3h1t6o=316,4h2t1o=421. Original teacher reinforces summands written by descending place values even if ordinary addition rearranges operands. Activity2 actual TWO students roll THREE number cubes for largest, smallest, and another arrangement, write each in numerals and expanded form; dice outcomes are not provided and not invented. Teacher checks real diagrams/dice and genuine different representations. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "Expanded form of a three-digit numeral uses hundreds first, tens second, ones third: 357=300+50+7. Normal addition permits 40+100+3=143 but standard expanded form is100+40+3. For a nonzero three-digit digit set, greatest arrangement is descending and smallest ascending (avoid leading zero when composing three-digit numerals). This lesson directly addresses CCSS:2.NBT.A.1, CCSS:2.NBT.A.3. ORIGINAL task evidence: Activity1 publisher 3h5t7o=357→300+50+7,1h9t2o=192,2h3t8o=238,3h1t6o=316,4h2t1o=421. Original teacher reinforces summands written by descending place values even if ordinary addition rearranges operands. Activity2 actual TWO students roll THREE number cubes for largest, smallest, and another arrangement, write each in numerals and expanded form; dice outcomes are not provided and not invented. Teacher checks real diagrams/dice and genuine different representations.",
             "Source357=300+50+7;192=100+90+2;238=200+30+8;316=300+10+6;421=400+20+1; original teacher example143=100+40+3. FIRST-PARTY PRACTICE BOUNDARY: Numeric HTO to expanded components, evaluate expanded sums, maximize/minimize three digits, verify zero place.",
             "1. Review the ORIGINAL lesson warm-up: Original True/False 800+90+7=897 TRUE;156=50+100+6 TRUE;407=70+400 FALSE;632=22+10+600 TRUE (not conventional expanded form). 2. Study original learner Activity1 and exact publisher quantities: Activity1 publisher 3h5t7o=357→300+50+7,1h9t2o=192,2h3t8o=238,3h1t6o=316,4h2t1o=421. Original teacher reinforces summands written by descending place values even if ordinary addition rearranges operands. Activity2 actual TWO students roll THREE number cubes for largest, smallest, and another arrangement, write each in numerals and expanded form; dice outcomes are not provided and not invented. Teacher checks real diagrams/dice and genuine different representations. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: 632=22+10+600 is TRUE arithmetic but not standard place-by-place expanded form. Do not swap digits and claim numerical representation stays unchanged. A zero-place has value zero, never silently changes the hundreds place. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: True/False reasoning, base-ten source images, original THREE physical number cube outcomes and partner choices require teacher; restricted Cool-down unavailable.",
             "632=22+10+600 is TRUE arithmetic but not standard place-by-place expanded form. Do not swap digits and claim numerical representation stays unchanged. A zero-place has value zero, never silently changes the hundreds place. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L5: Expanded form of a three-digit numeral uses hundreds first, tens second, ones third: 357=300+50+7. Normal addition permits 40+100+3=143 but standard expanded form is100+40+3. For a nonzero three-digit digit set, greatest arrangement is descending and smallest ascending (avoid leading zero when composing three-digit numerals). True/False reasoning, base-ten source images, original THREE physical number cube outcomes and partner choices require teacher; restricted Cool-down unavailable."],false),
        new(73,"PED:US-CCSS-MATH:G2:U05:L06","https://im.kendallhunt.com/k5/teachers/grade-2/unit-5/lesson-6/preparation.html","9d63ab9c21dc75ff605e8defc2f51386bd99ed8b3bce8c1f25af0319cd0f5e5e",
            ["CCSS:2.NBT.A.3"],
            ["Learning goal: You will represent numbers using unit form, base-ten numerals, expanded form, and words.\nIn previous lessons, you learned different ways that can be used to represent numbers. In this lesson, you are introduced to one more way to represent numbers, that is, using words. You gain more experience with numbers represented in all the different ways you have worked with so far.",
             "Key ideas:\n- Read, write, and represent three-digit numbers, including number names\n- In previous lessons, you learned different ways that can be used to represent numbers\n- Measurement units must be equal in size and placed or interpreted without gaps, overlaps, or a shifted starting point.",
             "Example 1: Which one doesn’t belong? A Caption: A B Caption: B C Caption: C D Caption: D\nApproach: “Which representations best help you understand the value of the number? Explain.” (A has a lot of words to read, so I prefer C. D tells you how many of each. With B you just have to count the blocks.)\nExample 2: Fill in the blanks to represent 248 with words. two ___ forty- ___ Fill in the blanks to represent 562 with words. ___ hundred ___ - ___ Represent this number with words. Represent 627 with words. Represent \\(900 + 50 + 1\\) with words. Represent three hundred eighteen in two different ways.\nApproach: Choose the required unit, align equal units from the endpoint, measure without gaps or overlaps, and record the result with its unit.",
             "Step 1: Identify what needs to be measured.\nStep 2: Choose the required unit and correct starting point.\nStep 3: Place or interpret equal-size units accurately.\nStep 4: Count or calculate the units and record the measure.\nStep 5: Check the endpoint, scale, and unit label.",
             "Common mistake: using unequal units, leaving gaps, overlapping units, or starting at the wrong point. Check the unit and endpoints.",
             "You will represent numbers using unit form, base-ten numerals, expanded form, and words. In previous lessons, you learned different ways that can be used to represent numbers."],
            ["Original 2021 IM Grade2 Unit5 Lesson6 — Represent Numbers in Different Ways. Which One Doesn't Belong? Publisher original four images: A 'three hundred twenty-five', B3 hundreds2 tens5 ones (=325), C numeral253, D unit form3 hundreds2 tens5 ones (=325). Valid multiple justifications must be accepted, not one hard-coded choice. Activity1 text for 248 'two hundred forty-eight',562 'five hundred sixty-two', diagram4h3t3o 'four hundred thirty-three', numeral627, sum900+50+1 'nine hundred fifty-one', and 'three hundred eighteen' in TWO different representations. Activity2 original classroom group3–4 poster represents teacher-assigned THREE-digit number as numeral, base-ten picture, expanded form and WORDS (optionally tens-and-ones form), actual gallery walk. Teacher must review spelling and partner explanations. All numerical Edulytics exercises are independently authored; real classroom source pictures and written responses remain teacher-reviewed.",
             "Write three-digit numbers as numerals, expanded form and English names with correct place value: 248=200+40+8, name 'two hundred forty-eight'; 562=500+60+2; 433=400+30+3; 627=600+20+7; 951=900+50+1;318=300+10+8. The four warm-up figures include THREE equivalent325 representations and an alternate253, but learners may identify another odd one with a defensible visual category. Number names for21–99 with nonzero ones generally hyphenate (e.g. forty-eight). This lesson directly addresses CCSS:2.NBT.A.3. ORIGINAL task evidence: Activity1 text for 248 'two hundred forty-eight',562 'five hundred sixty-two', diagram4h3t3o 'four hundred thirty-three', numeral627, sum900+50+1 'nine hundred fifty-one', and 'three hundred eighteen' in TWO different representations. Activity2 original classroom group3–4 poster represents teacher-assigned THREE-digit number as numeral, base-ten picture, expanded form and WORDS (optionally tens-and-ones form), actual gallery walk. Teacher must review spelling and partner explanations.",
             "Original source values248,562,433,627,951,318; warm-up figures words325, blocks325, numeric253 and unit-form325. Original 253 anchor:2h5t3o and200+50+3. FIRST-PARTY PRACTICE BOUNDARY: Numeric cross-representation place values plus teacher-reviewed open English names with learner-written response.",
             "1. Review the ORIGINAL lesson warm-up: Which One Doesn't Belong? Publisher original four images: A 'three hundred twenty-five', B3 hundreds2 tens5 ones (=325), C numeral253, D unit form3 hundreds2 tens5 ones (=325). Valid multiple justifications must be accepted, not one hard-coded choice. 2. Study original learner Activity1 and exact publisher quantities: Activity1 text for 248 'two hundred forty-eight',562 'five hundred sixty-two', diagram4h3t3o 'four hundred thirty-three', numeral627, sum900+50+1 'nine hundred fifty-one', and 'three hundred eighteen' in TWO different representations. Activity2 original classroom group3–4 poster represents teacher-assigned THREE-digit number as numeral, base-ten picture, expanded form and WORDS (optionally tens-and-ones form), actual gallery walk. Teacher must review spelling and partner explanations. 3. Represent authentic source quantities with units, true base-ten trade logic and intermediate values. 4. Explain a correct strategy and a likely place-value error: 253 is NOT325; writing numerals only doesn't demonstrate English number naming. Missing a hundred or transposing hundreds/tens changes value; only teacher can grade a defensible multiple-solution warm-up, student-authored poster or speech. 5. Complete remaining original Source Activity2 with actual teacher-supervised blocks/images/discussion rather than fabricated evidence. 6. Solve new source-aligned Edulytics first-party exact mathematics. 7. Have educator review drawing, physical construction, open reasoning, names and discussions: Teacher verifies actual original images, full written English forms (including spelling), alternate valid warm-up justifications and physical gallery poster; restricted Cool-down unavailable.",
             "253 is NOT325; writing numerals only doesn't demonstrate English number naming. Missing a hundred or transposing hundreds/tens changes value; only teacher can grade a defensible multiple-solution warm-up, student-authored poster or speech. A machine-graded numeric response never proves that original visual/personalized activities or restricted teacher-only assessments were completed.",
             "Original IM2021 G2 U05 L6: Write three-digit numbers as numerals, expanded form and English names with correct place value: 248=200+40+8, name 'two hundred forty-eight'; 562=500+60+2; 433=400+30+3; 627=600+20+7; 951=900+50+1;318=300+10+8. The four warm-up figures include THREE equivalent325 representations and an alternate253, but learners may identify another odd one with a defensible visual category. Number names for21–99 with nonzero ones generally hyphenate (e.g. forty-eight). Teacher verifies actual original images, full written English forms (including spelling), alternate valid warm-up justifications and physical gallery poster; restricted Cool-down unavailable."],false)
    ];
    public static string VersionFor(int ordinal)=>$"usccss-g2-u05-source-v2-ordinal{ordinal}";
    private static Entry? Find(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>
        d.PackCode==MathematicsCurriculumPackRegistry.CommonCoreCode &&
        d.VersionCode=="CCSSM-2010" && d.ContentVersion=="phase30-common-core-rich-content-v1"
          ? Entries.SingleOrDefault(x=>x.Code==l.LessonCode):null;
    public static bool IsTarget(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>Find(d,l)!=null;
    private static void Guard(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,Entry e)
    {
        if(e.Url!=l.SourceUrl||!string.Equals(e.Sha,l.CanonicalBodySha256,StringComparison.OrdinalIgnoreCase)||
            !l.OutcomeCodes.SequenceEqual(e.Outcomes))
            throw new InvalidOperationException($"G2 original source identity drift at ordinal {e.Ordinal}");
    }
    private static bool Match(string[] a,string[] b)=>a.SequenceEqual(b);
    private static string[] Fields(CanonicalLessonContentPackTranslation x)=>
        [x.Explanation,x.KeyConceptsAndRules,x.WorkedExamples,x.StepByStepSolutions,x.CommonMistakes,x.QuickSummary];
    private static string[] Fields(CurriculumLessonContentTranslation x)=>
        [x.Explanation,x.KeyConceptsAndRules,x.WorkedExamples,x.StepByStepSolutions,x.CommonMistakes,x.QuickSummary];
    private static bool LegacyApproved(CanonicalLessonContentPackTranslation t,Entry e)=>
        e.Legacy&&t.Explanation==e.Before[0]&&t.QuickSummary==e.Before[5]&&
        t.KeyConceptsAndRules.Contains("hundred",StringComparison.OrdinalIgnoreCase)&&
        t.StepByStepSolutions.StartsWith("Step 1:",StringComparison.Ordinal);
    public static void Apply(CanonicalLessonContentPackDocument d)
    {
        foreach(var l in d.Lessons)
        {
            var e=Find(d,l);if(e==null)continue;
            Guard(d,l,e);var t=l.Translations.Single(x=>x.CultureCode=="en");
            if(Match(Fields(t),e.After))continue;
            if(!Match(Fields(t),e.Before)&&!LegacyApproved(t,e))
                throw new InvalidOperationException($"G2 source learner predecessor mismatch ordinal {e.Ordinal}");
            t.Explanation=e.After[0];t.KeyConceptsAndRules=e.After[1];t.WorkedExamples=e.After[2];
            t.StepByStepSolutions=e.After[3];t.CommonMistakes=e.After[4];t.QuickSummary=e.After[5];
        }
    }
    public static string GetExpectedContentVersion(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string previous)
    {
        var e=Find(d,l);return e is null?previous:VersionFor(e.Ordinal);
    }
    public static bool CanUpgradeExisting(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)
    {
        var e=Find(d,l);
        return e is not null && (prior==CommonCoreRichContentCorrections.CorrectionContentVersion||
            (e.Legacy&&prior==CommonCoreG2HundredsPlaceValueSourceCorrections.CorrectedContentVersion));
    }
    public static void ValidateExistingBodyBeforeUpgrade(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,
        string prior,IReadOnlyCollection<CurriculumLessonContentTranslation> rows)
    {
        var e=Find(d,l)??throw new InvalidOperationException("Not G2 U05 target");
        Guard(d,l,e);
        if(!CanUpgradeExisting(d,l,prior))
            throw new InvalidOperationException($"Unexpected persisted G2 U05 predecessor ordinal {e.Ordinal}");
        if(rows.Count==0)return;
        if(rows.Count!=1||rows.Single().CultureCode!="en")throw new InvalidOperationException("Persisted language drift");
        var t=rows.Single();
        // Legacy two-stage correction pre-validates all its approved old learner text.
        if(!Match(Fields(t),e.Before))
            throw new InvalidOperationException($"Stored G2 U05 original six-field predecessor mismatch {e.Ordinal}");
    }
}
